Q: Same projection mappping in IQueryable.Select but with Varied Child Collection filters in EF6 A: <h2>Workaround</h2>
<p>8 months after asking this question and using EF, I figured most of the time I don't need to over-complicate it. It is actually pretty easy to just use 2 separate queries and combine the queries using <code>ToLookup()</code>, without causing 1+N queries (such as using for loop to query labels for each product):</p>
<p>(This method also comes in handy to solve the issue of cartesian explosion for a one to many result where the &quot;one&quot; part contains a large amount of data.)</p>
<pre class="lang-cs prettyprint-override"><code>// the filter criteria for the parent entity
var productQuery = context.Product
  .AsExpandable()
  .Where(product =&gt; product.ProductType == productType);

var productResult = await productQuery
// the mapping can be extracted easily to be reused
  .Select(p =&gt; new YourProductDTO(...))
  .ToListAsync();

// the look up (which is just a dictionary of collections as far as I understand)
var labelResult = productQuery
  .Select(p =&gt; p.Labels)
  .Where(l =&gt; l.CustomerID == customerID)
  .Select(l =&gt; new YourLabelDTO(...))
  .ToLookup(l =&gt; l.ProductKey);

// iterate through the parent result to assign the filtered child navigation properties
for(var productDto in productResult) {
  if(labelResult.Contains(productDTO.ProductKey))
    productDTO.Labels = labelResult[productDTO.ProductKey];
}

return productDTO;
</code></pre>
<h2>Original Solution (Long and Sad)</h2>
<p>Note: I stopped using this as it is just too verbose and too much work to achieve a result that can be done in 2 queries easily.</p>
<p>Below is my original solution that requires manually creating an expression, it worked for this exact pattern, but I didn't get to test it on any other situations. Also note that there's probably a simplier way to do this by utilizing LinqKit betterm but I couldn't figure it out. The idea is to have a base expression that maps the original entity to a DTO, and then have a <code>ExpressionVisitor</code> to help modifying it to apply the navigation property expression with filter onto it. All this is just to achieve what EF Core, as far as I know, can do with simply <code>.Include(product =&gt; product.Labels.Where(l =&gt; ...))</code>.</p>
<p>My Expression Visitor looks something like this. This is the only time I needed to manually deal with <code>Expressions</code>, and I believe there must be some better way to implement this idea.</p>
<pre class="lang-cs prettyprint-override"><code>public static class ProjectionExpressionBuilder {
  public static ProjectionNavigationBuilder&lt;TSource, TTarget&gt; 
    FromBaseProjection&lt;TSource, TTarget&gt;(
      Expression&lt;Func&lt;TSource, TTarget&gt;&gt; sourceExpression
    ) {
    return new ProjectionNavigationBuilder&lt;TSource, TTarget&gt;(sourceExpression);
  }

  public class ProjectionNavigationBuilder&lt;TSource, TTarget&gt; {
    private Expression _currentBody;
    private readonly ParameterExpression _sourceParameter;

    public ProjectionNavigationBuilder(Expression&lt;Func&lt;TSource, TTarget&gt;&gt; root) {
      _currentBody = root.Body;
      _sourceParameter = root.Parameters[0];
    }

    public ProjectionNavigationBuilder&lt;TSource, TTarget&gt; With&lt;TProperty&gt;(
      Expression&lt;Func&lt;TTarget, TProperty&gt;&gt; targetProperty,
      Expression&lt;Func&lt;TSource, TProperty&gt;&gt; navigationExpression) {
      var targetMember = (targetProperty.Body as MemberExpression)?.Member
        ?? throw new Exception(&quot;Target must be a property access.&quot;);

      // Use the new expression for the target navigation property
      _currentBody = TargetMemberBindingVisitor.Update(
        _currentBody,
        targetMember,
        navigationExpression,
        _sourceParameter);

      return this;
    }

    public Expression&lt;Func&lt;TSource, TTarget&gt;&gt; Build() =&gt;
      Expression.Lambda&lt;Func&lt;TSource, TTarget&gt;&gt;(_currentBody, _sourceParameter)
      .Expand();

    private class TargetMemberBindingVisitor: ExpressionVisitor {
      private readonly MemberInfo _targetMember;
      private readonly Expression _newNavigationExpression;
      private readonly ParameterExpression _oldNavParam;
      private readonly ParameterExpression _rootParam;
      private bool _hasUpdatedRoot = false;

      public TargetMemberBindingVisitor
        (MemberInfo targetMember, 
         LambdaExpression newNavigationExpression, 
         ParameterExpression rootParam) {
        _targetMember = targetMember;
        _newNavigationExpression = newNavigationExpression.Body;
        _oldNavParam = newNavigationExpression.Parameters[0];
        _rootParam = rootParam;
      }

      public static Expression Update
        (Expression rootBody, MemberInfo targetMember, 
         LambdaExpression newNavigationExpression, ParameterExpression rootParam)
        =&gt; new TargetMemberBindingVisitor(targetMember, newNavigationExpression, 
             rootParam)
             .Visit(rootBody);

      protected override Expression VisitParameter(ParameterExpression node)
        =&gt; node == _oldNavParam ? _rootParam : base.VisitParameter(node);

      protected override Expression VisitMemberInit(MemberInitExpression node) {
        if (_hasUpdatedRoot || node.Type != typeof(TTarget))
          return base.VisitMemberInit(node);

        _hasUpdatedRoot = true;

        var newBindings = node.Bindings
          .Where(b =&gt; b.Member.Name != _targetMember.Name)
          // use correct parameter
          .Concat(new[] { 
            Expression.Bind(_targetMember, Visit(_newNavigationExpression)) 
          })
          .ToList();

        return node.Update(node.NewExpression, newBindings);
      }
    }
  }
}
</code></pre>
<p>Then it can be used easier (IMO) than having the a huge select query:</p>
<pre class="lang-cs prettyprint-override"><code>public List&lt;ProductsDTO&gt; ListProductWithLabels(int productKey, string labelType) {
  using (MyDBContext context = new MyDBContext()) {
    return context.Product
    .AsNoTracking()
    .Where(product =&gt; product.ProductKey == productKey)
    .Select(
      ProductDTO.ToProjectedWithLabelsFilteredByLabelType(labelType))
    .ToList();
  }
}

// returns the actual projection used in select in linq-to-sql
public static Expression&lt;Func&lt;Product, ProductDTO&gt;&gt; 
  ToProjectedWithLabelsFilteredByLabelType(string labelType) {
    var initProductDtoExpression = ToProductDTO();
    var navigationPropertyExpression = LabelsDTO.ToLabelDTOFilteredByLabelType(labelType);
    return ProjectionExpressionBuilder.FromBaseProjection(initDTOExpression)
      .With(
        dto =&gt; dto.Labels,
        product =&gt; brandFilter.Invoke(product.Labels))
      .Build();
}

// the extracted logic to convert Product to ProductDTO I was asking for
public static Expression&lt;Func&lt;Product, ProductDTO&gt;&gt; ToProductDTO() {
  return p =&gt; p == null ? null : new ProductDTO
  {
    productName = product.Name,
    productDescription = product.Description,
    productSKU = product.SKU
    // other needed fields
  }
}
</code></pre>
